# alerta-produtor.tf — a regra que observa o CONTRATO, nao a falha do job

resource "aws_sns_topic" "alerta_precificacao" {
  name = "${var.projeto}-alerta-contrato-precificacao"
}

resource "aws_sns_topic_subscription" "time_precificacao" {
  topic_arn = aws_sns_topic.alerta_precificacao.arn
  protocol  = "email"
  endpoint  = var.email_time_precificacao
}

resource "aws_cloudwatch_event_rule" "contrato_violado" {
  name        = "${var.projeto}-contrato-produtos-violado"
  description = "Evento de DOMINIO publicado pelo job quando ha registro em quarentena -- nao e o alerta nativo de falha do L65"

  event_pattern = jsonencode({
    source      = ["cadencia.qualidade-dado"]
    detail-type = ["ContratoDadoViolado"]
  })
}

resource "aws_cloudwatch_event_target" "avisa_precificacao" {
  rule = aws_cloudwatch_event_rule.contrato_violado.name
  arn  = aws_sns_topic.alerta_precificacao.arn
}

resource "aws_sns_topic_policy" "permite_eventbridge" {
  arn    = aws_sns_topic.alerta_precificacao.arn
  policy = data.aws_iam_policy_document.eventbridge_publica.json
}

data "aws_iam_policy_document" "eventbridge_publica" {
  statement {
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.alerta_precificacao.arn]
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

# Permissao adicional ao papel do JOB (job.tf, do L65): sem isto, o
# put_events do script falha com AccessDenied, e a quarentena grava mas o
# alerta nunca sai.
data "aws_iam_policy_document" "job_publica_evento" {
  statement {
    effect    = "Allow"
    actions   = ["events:PutEvents"]
    resources = ["arn:aws:events:${var.regiao}:${var.conta_id}:event-bus/default"]
  }
}

resource "aws_iam_role_policy" "job_publica_evento" {
  role   = aws_iam_role.job.id
  policy = data.aws_iam_policy_document.job_publica_evento.json
}

# O job tambem precisa escrever no prefixo NOVO de quarentena -- estende a
# policy de escrita do L65 (job.tf), que so cobria prata/produtos/*.
data "aws_iam_policy_document" "job_escreve_quarentena" {
  statement {
    effect    = "Allow"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
    resources = [
      "arn:aws:s3:::${var.bucket_lake}",
      "arn:aws:s3:::${var.bucket_lake}/quarentena/produtos/*",
    ]
  }
}

resource "aws_iam_role_policy" "job_escreve_quarentena" {
  role   = aws_iam_role.job.id
  policy = data.aws_iam_policy_document.job_escreve_quarentena.json
}

// ConfirmarCorrecaoEReprocessar.cs — so declara corrigido com numero, nao com "deve ter dado certo"

using Amazon.Glue;
using Amazon.Glue.Model;
using Amazon.S3;
using Amazon.Lambda.Core;

namespace Cadencia.QualidadeDado;

public record ConfirmarCorrecao(string Dia); // "2026-07-19", ja validado antes de chegar aqui

public class ConfirmarCorrecaoHandler
{
    private static readonly AmazonGlueClient _glue = new();
    private static readonly AmazonS3Client _s3 = new();
    private const string Bucket = "cadencia-lake";

    // Exposta ao time de Precificacao via API Gateway com autorizacao propria
    // -- e o botao que eles apertam depois de corrigir a unidade na origem.
    public async Task<string> ConfirmarAsync(ConfirmarCorrecao pedido, ILambdaContext contexto)
    {
        // 1. Reprocessa o dia -- seguro porque o job e idempotente (L65):
        //    apaga e reescreve prata E quarentena do zero.
        var execucao = await _glue.StartJobRunAsync(new StartJobRunRequest
        {
            JobName = "cadencia-transformar-produtos",
            Arguments = new Dictionary<string, string> { ["--dt"] = pedido.Dia },
        });

        await AguardarConclusaoAsync(execucao.JobRunId, contexto);

        // 2. NAO declara sucesso so porque o job terminou SUCCEEDED -- isso
        //    prova so que o job rodou sem excecao, nao que a correcao
        //    funcionou. A prova de verdade e a CONTAGEM da quarentena.
        var restantes = await ContarObjetosAsync($"quarentena/produtos/dt={pedido.Dia}/");

        contexto.Logger.LogInformation(
            $"reprocessamento de dt={pedido.Dia} concluido: {restantes} objeto(s) " +
            $"ainda em quarentena");

        if (restantes > 0)
        {
            throw new InvalidOperationException(
                $"correcao incompleta: {restantes} registro(s) continuam violando o " +
                "contrato apos o reprocessamento -- confira o ruleset ou a origem");
        }

        return $"dt={pedido.Dia} reprocessado, 0 registros em quarentena";
    }

    private async Task<int> ContarObjetosAsync(string prefixo)
    {
        var resposta = await _s3.ListObjectsV2Async(new()
        {
            BucketName = Bucket,
            Prefix = prefixo,
        });
        return resposta.S3Objects.Count;
    }

    private async Task AguardarConclusaoAsync(string jobRunId, ILambdaContext contexto)
    {
        // Poll simples; producao real trocaria por Step Functions com wait
        // state, como o L25 desta serie mostra para orquestracao mais longa.
        JobRun? execucao;
        do
        {
            await Task.Delay(TimeSpan.FromSeconds(15));
            var resposta = await _glue.GetJobRunAsync(new GetJobRunRequest
            {
                JobName = "cadencia-transformar-produtos",
                RunId = jobRunId,
            });
            execucao = resposta.JobRun;
        } while (execucao.JobRunState is "RUNNING" or "STARTING" or "STOPPING");

        if (execucao.JobRunState != "SUCCEEDED")
        {
            throw new InvalidOperationException(
                $"job terminou em {execucao.JobRunState}: {execucao.ErrorMessage}");
        }
    }
}
